    $unique_char2 = $unique_chars[array_rand($unique_chars)];
    $unique_char3 = $unique_chars[array_rand($unique_chars)];

    // Combine the components into a password
    $password = $word . $number . $symbol . $unique_char1 . $unique_char2 . $unique_char3;

    // Check if the password contains any repetitive patterns
    if (!preg_match('/(.)\1{2,}/', $password)) {
        // Add the password to the list
        $passwords[] = $password;
