```
#include <cmath>
// Function to calculate the t-statistic
double t_statistic(double mean1, double mean2, double s1, double s2, int n1, int n2) {
    return (mean1 - mean2) / sqrt((s1 * s1 / n1) + (s2 * s2 / n2));
}
// Function to calculate the degrees of freedom
int degrees_of_freedom(int n1, int n2) {
    return n1 + n2 - 2;
}
// Function to calculate the p-value
double p_value(double t, int df) {
    double p = 2.0 * (1.0 - std::t_distribution<double>(df)(std::abs(t)));
    if (p > 1.0) {
        p = 2.0 - p;
    }
    return p;
}
