    int n2 = 25;
    // Calculate the t-statistic
    double t = t_statistic(mean1, mean2, s1, s2, n1, n2);
    // Calculate the degrees of freedom
    int df = degrees_of_freedom(n1, n2);
    // Calculate the p-value
    double p = p_value(t, df);
    // Output the results
    std::cout << "t = " << t << std::endl;
    std::cout << "df = " << df << std::endl;
