  receiver = c("Buyer 1", "Buyer 2", "Buyer 3", "Buyer 4", "Buyer 5"),
  amount = c(100, 200, 300, 400, 500)
)
transactions <- transactions %>%
  mutate(hash = generate_hash(paste(id, sender, receiver, amount, sep = "")))
```
Now, we can create a function to verify the authenticity of each block by checking the hash code of the previous block. We can use the `tail()` function to get the hash code of the last block in the chain.
```
verify_blockchain <- function(transactions){
  for(i in 2:nrow(transactions)){
    prev_hash <- tail(transactions$hash, n = 1)
    curr_hash <- transactions[i, "hash"]
    if(prev_hash != curr_hash){
      return(FALSE)
    }
  }
  return(TRUE)
}
```
