            var sentences = tokenizer.Tokenize(text);
            // Create a bigram model
            var corpusReader = new PlaintextCorpusReader();
            var corpus = corpusReader.Corpus("path/to/corpus");
            var bigramModel = new NgramModel(2, corpus);
            // Evaluate coherence and flow of each sentence
            foreach (var sentence in sentences)
            {
                var sentenceProb = bigramModel.Evaluate(sentence);
                Console.WriteLine("Sentence: " + sentence);
                Console.WriteLine("Probability: " + sentenceProb);
            }
            Console.ReadLine();
        }
    }
}
```
