Optimizing the C++ code for computing the median of five numbers can be done by using the "median of medians" algorithm. This algorithm reduces the number of comparisons needed to find the median to a maximum of 12, while the standard method requires 16 comparisons. The optimization process involves breaking the five numbers into groups of three, finding the median of each group, and then finding the median of those medians. The final median can then be found by comparing the remaining two numbers to the median of medians. Here is the optimized C++ code that implements this formula:
```
int median(int a, int b, int c) {
    if (a > b) {
        if (b > c) return b;
        else if (a > c) return c;
        else return a;
    } else {
        if (a > c) return a;
        else if (b > c) return c;
        else return b;
    }
}
int median_of_medians(int arr[], int n) {
    if (n <= 5) return median(arr[0], arr[1], arr[2], arr[3], arr[4]);
    int medians[(n + 4) / 5];
    int i, j;
    for (i = 0, j = 0; i < n / 5; i++, j += 5) {
        medians[i] = median(arr[j], arr[j + 1], arr[j + 2], arr[j + 3], arr[j + 4]);
    }
    if (j < n) {
        medians[i] = median(arr[j], arr[j + 1], arr[j + 2], arr[j + 3], arr[j + 4]);
        i++;
    }
    int median_of_medians = median_of_medians(medians, i);
    int pivot = partition(arr, n, median_of_medians);
    if (pivot == (n - 1) / 2) {
        return median_of_medians;
    } else if (pivot < (n - 1) / 2) {
        return median_of_medians(arr + pivot + 1, n - pivot - 1);
    } else {
        return median_of_medians(arr, pivot);
    }
}
int median(int arr[], int n) {
    return median_of_medians(arr, n);
}
```

