function [new_sentence, synonyms] = replace_word_with_synonym(sentence, target_word)
    % Use the Datamuse API to get a list of synonyms for the target word
    url = sprintf('https://api.datamuse.com/words?rel_syn=%s', target_word);
    response = webread(url);
    synonyms = {response.word};
    % Loop through the synonyms and find the one that best fits the context
    best_synonym = '';
    for i = 1:length(synonyms)
        % Replace the target word with the synonym in the sentence
        new_sentence = strrep(sentence, target_word, synonyms{i});
        % Check if the new sentence makes sense in context
        if ~contains(new_sentence, 'inappropriate word') % Add your own logic here to determine if the new sentence is appropriate
            best_synonym = synonyms{i};
            break;
        end
    end
    % If no appropriate synonym was found, use the original sentence
    if isempty(best_synonym)
        new_sentence = sentence;
        best_synonym = target_word;
    end
    % Return the new sentence and the list of synonyms for the user to choose from
    synonyms = [target_word, synonyms];
    synonyms = synonyms(~strcmp(synonyms, best_synonym)); % Remove the best synonym from the list
end
